// Some portions generated by Claude

/**
 * A Shift-, ⌘- or Ctrl-click adds a node to the selection or takes it out. The node a plain click showed (`anchor`)
 * joins first, so a click on one node and a ⌘-click on another select both.
 */
export function toggleInSelection(current: ReadonlySet<string>, nodeId: string, anchor: string | null): Set<string> {
  const next = new Set(current);
  if (anchor !== null && anchor !== nodeId) next.add(anchor);
  if (current.has(nodeId)) next.delete(nodeId);
  else next.add(nodeId);
  return next;
}

/** A box drawn with Shift, ⌘ or Ctrl adds what it touches, and the node a plain click showed; unchanged, the same set. */
export function addToSelection<S extends ReadonlySet<string>>(
  current: S,
  nodeIds: Iterable<string>,
  anchor: string | null,
): S | Set<string> {
  const next = new Set(current);
  if (anchor !== null) next.add(anchor);
  for (const nodeId of nodeIds) next.add(nodeId);
  return next.size === current.size ? current : next;
}
